+fn run(program: [str], max_steps: i64) -> i64 {let n = len(program)
+    let stack = []
+    let pc = 0
+    let steps = 0
+    while pc < n {
+        if steps >= max_steps {
+            return -3
+        }
+        steps = steps + 1
+        let ins = parse_instr(program[pc])
+        let op = ins[0]
+        let arg = ins[1]
+        let sz = len(stack)
+        let next = pc + 1
+        let keep = sz
+        let vals = []
+        if op < 0 {
+            return -2
+        } else if op == 1 {
+            vals = [arg]
+        } else if op >= 2 && op <= 4 {
+            if sz < 2 {
+                return -1
+            }
+            let a = stack[sz - 2]
+            let b = stack[sz - 1]
+            let r = a + b
+            if op == 3 {
+                r = a - b
+            } else if op == 4 {
+                r = a * b
+            }
+            keep = sz - 2
+            vals = [r]
+        } else if op == 5 {
+            if sz < 1 {
+                return -1
+            }
+            vals = [stack[sz - 1]]
+        } else if op == 6 {
+            if sz < 2 {
+                return -1
+            }
+            keep = sz - 2
+            vals = [stack[sz - 1], stack[sz - 2]]
+        } else if op == 7 {
+            if sz < 1 {
+                return -1
+            }
+            keep = sz - 1
+        } else if op == 8 {
+            if sz < 1 {
+                return -1
+            }
+            let top = stack[sz - 1]
+            keep = sz - 1
+            if arg < 0 || arg >= n {
+                return -4
+            }
+            if top == 0 {
+                next = arg
+            }
+        } else if op == 9 {
+            if arg < 0 || arg >= n {
+                return -4
+            }
+            next = arg
+        } else if op == 10 {
+            break
+        } else {
+            return -2
+        }
+        let base = []
+        let j = 0
+        while j < keep {
+            base = arr_push(base, stack[j])
+            j = j + 1
+        }
+        let q = 0
+        while q < len(vals) {
+            base = arr_push(base, vals[q])
+            q = q + 1
+        }
+        stack = base
+        pc = next
+    }
+    if len(stack) == 0 {
+        return -1
+    }
